#include <iostream>
#include <iomanip>
#include <cmath>

int main() {
    int number = 0;
    if (std::cin >> number) {
        // Integral stream bases (sticky)
        std::cout << number << " in hexadecimal is: " << std::hex << number << "\n";
        std::cout << std::dec << number << " in octal is: " << std::oct << number << "\n";
        std::cout << std::setbase(10) << number << " in decimal is: " << number << "\n";

        // Floating-point precision (sticky)
        double root2 = std::sqrt(2.0);
        std::streamsize savedPrec = std::cout.precision();

        std::cout << std::fixed;
        for (int places = 0; places <= 4; ++places) {
            std::cout.precision(places);
            std::cout << "P" << places << ": " << root2 << "\n";
        }

        // Restore saved precision
        std::cout.precision(savedPrec);
    }
    return 0;
}

#include <iostream>

// User-defined unparameterized stream manipulators
std::ostream& tab(std::ostream& output) {
    return output << '\t';
}

std::ostream& endLine(std::ostream& output) {
    return output << '\n' << std::flush;
}

int main() {
    char word[10];

    // Safe input: read at most 4 chars plus '\0'
    std::cin.width(5);
    if (std::cin >> word) {
        // Demonstrate non-sticky behavior of cout.width
        std::cout.width(6);
        std::cout << word << tab << "[first]" << endLine;
        // Since width reset to 0, next output is unpadded
        std::cout << word << tab << "[second]" << endLine;
    }
    return 0;
}
